const updateReconhecimento = `-- name: UpdateReconhecimento :one
UPDATE reconhecimentos SET data_inicio = $1, data_fim = $2, imoveis_residenciais = $3,
    imoveis_comerciais = $4, imoveis_outros = $5, habitantes = $6, quarteiroes = $7,
    pontos_estrategicos = $8, armadilhas = $9, terrenos_baldios = $10,
    caes = $11, gatos = $12, roedores = $13, latitude = $14, longitude = $15, altitude = $16,
    distancia_centro = $17, infraestrutura = $18, riscos = $19, observacao = $20,
    atualizado_em = now()
WHERE id = $21 AND deleted_at IS NULL
RETURNING id, bairro_id, ciclo_id, data_inicio, data_fim, imoveis_residenciais, imoveis_comerciais, imoveis_outros, habitantes, quarteiroes, pontos_estrategicos, armadilhas, terrenos_baldios, caes, gatos, roedores, latitude, longitude, altitude, distancia_centro, infraestrutura, riscos, observacao, criado_por, criado_em, atualizado_em, deleted_at, deleted_by
`

type UpdateReconhecimentoParams struct {
	DataInicio          pgtype.Date   `json:"data_inicio"`
	DataFim             pgtype.Date   `json:"data_fim"`
	ImoveisResidenciais pgtype.Int4   `json:"imoveis_residenciais"`
	ImoveisComerciais   pgtype.Int4   `json:"imoveis_comerciais"`
	ImoveisOutros       pgtype.Int4   `json:"imoveis_outros"`
	Habitantes          pgtype.Int4   `json:"habitantes"`
	Quarteiroes         pgtype.Int4   `json:"quarteiroes"`
	PontosEstrategicos  pgtype.Int4   `json:"pontos_estrategicos"`
	Armadilhas          pgtype.Int4   `json:"armadilhas"`
	TerrenosBaldios     pgtype.Int4   `json:"terrenos_baldios"`
	Caes                pgtype.Int4   `json:"caes"`
	Gatos               pgtype.Int4   `json:"gatos"`
	Roedores            pgtype.Int4   `json:"roedores"`
	Latitude            pgtype.Float8 `json:"latitude"`
	Longitude           pgtype.Float8 `json:"longitude"`
	Altitude            pgtype.Float8 `json:"altitude"`
	DistanciaCentro     pgtype.Float8 `json:"distancia_centro"`
	Infraestrutura      []byte        `json:"infraestrutura"`
	Riscos              []byte        `json:"riscos"`
	Observacao          string        `json:"observacao"`
	ID                  int64         `json:"id"`
}

func (q *Queries) UpdateReconhecimento(ctx context.Context, arg UpdateReconhecimentoParams) (Reconhecimento, error) {
	row := q.db.QueryRow(ctx, updateReconhecimento,
		arg.DataInicio,
		arg.DataFim,
		arg.ImoveisResidenciais,
		arg.ImoveisComerciais,
		arg.ImoveisOutros,
		arg.Habitantes,
		arg.Quarteiroes,
		arg.PontosEstrategicos,
		arg.Armadilhas,
		arg.TerrenosBaldios,
		arg.Caes,
		arg.Gatos,
		arg.Roedores,
		arg.Latitude,
		arg.Longitude,
		arg.Altitude,
		arg.DistanciaCentro,
		arg.Infraestrutura,
		arg.Riscos,
		arg.Observacao,
		arg.ID,
	)
	var i Reconhecimento
	err := row.Scan(
		&i.ID,
		&i.BairroID,
		&i.CicloID,
		&i.DataInicio,
		&i.DataFim,
		&i.ImoveisResidenciais,
		&i.ImoveisComerciais,
		&i.ImoveisOutros,
		&i.Habitantes,
		&i.Quarteiroes,
		&i.PontosEstrategicos,
		&i.Armadilhas,
		&i.TerrenosBaldios,
		&i.Caes,
		&i.Gatos,
		&i.Roedores,
		&i.Latitude,
		&i.Longitude,
		&i.Altitude,
		&i.DistanciaCentro,
		&i.Infraestrutura,
		&i.Riscos,
		&i.Observacao,
		&i.CriadoPor,
		&i.CriadoEm,
		&i.AtualizadoEm,
		&i.DeletedAt,
		&i.DeletedBy,
	)
	return i, err
}
